import random
from collections import deque

# ACTIONS
NOOP = 0
MOVE_LEFT = 1
MOVE_RIGHT = 2
MOVE_UP = 3
MOVE_DOWN = 4
DO = 5
SLEEP = 6
PLACE_STONE = 7
PLACE_TABLE = 8
PLACE_FURNACE = 9
PLACE_PLANT = 10
MAKE_WOOD_PICK = 11
MAKE_STONE_PICK = 12
MAKE_IRON_PICK = 13
MAKE_WOOD_SWORD = 14
MAKE_STONE_SWORD = 15
MAKE_IRON_SWORD = 16

# player location in view
PR = 3
PC = 4

# mapping craft actions -> inventory key that should increase
CRAFT_KEY = {
    MAKE_WOOD_PICK: 'wood_pickaxe',
    MAKE_STONE_PICK: 'stone_pickaxe',
    MAKE_IRON_PICK: 'iron_pickaxe',
    MAKE_WOOD_SWORD: 'wood_sword',
    MAKE_STONE_SWORD: 'stone_sword',
    MAKE_IRON_SWORD: 'iron_sword',
}

def controller(obs, memory) -> int:
    view = obs['view']
    inv = obs['inventory']
    facing = obs['facing']
    daylight = obs.get('daylight', 1.0)
    sleeping = obs.get('sleeping', False)
    last_action = obs.get('last_action', None)

    # initialize memory
    if 'step' not in memory:
        memory['step'] = 0
    memory['step'] += 1

    if 'phase' not in memory:
        memory['phase'] = 1
    if 'attempts' not in memory:
        # attempts[action] = {'count': int, 'first_step': int, 'snapshot': {...}, 'blocked_until': step}
        memory['attempts'] = {}
    if 'last_exec' not in memory:
        memory['last_exec'] = None
    if 'wander_seed' not in memory:
        memory['wander_seed'] = random.randint(0, 1000000)
    rnd = random.Random(memory['wander_seed'] + memory['step'])

    # Helpers
    def in_bounds(r, c):
        return 0 <= r < 7 and 0 <= c < 9

    def cell(r, c):
        if not in_bounds(r, c):
            return 'edge'
        return view[r][c]

    def find_all(names):
        if isinstance(names, str):
            names = [names]
        coords = []
        for r in range(7):
            for c in range(9):
                if view[r][c] in names:
                    coords.append((r, c))
        return coords

    def find_any(names):
        return find_all(names)

    def nearest(target_names):
        if isinstance(target_names, str):
            target_names = [target_names]
        best = None
        bestd = 999
        for r in range(7):
            for c in range(9):
                if view[r][c] in target_names:
                    d = abs(r - PR) + abs(c - PC)
                    if d < bestd:
                        bestd = d
                        best = (r, c)
        return best

    def dir_to(dr, dc):
        if abs(dr) >= abs(dc):
            if dr < 0:
                return 'up'
            elif dr > 0:
                return 'down'
        if dc < 0:
            return 'left'
        elif dc > 0:
            return 'right'
        return None

    def facing_action_for(dir_str):
        return {'left': MOVE_LEFT, 'right': MOVE_RIGHT, 'up': MOVE_UP, 'down': MOVE_DOWN}[dir_str]

    def move_valid_dir(dir_str):
        if dir_str == 'left':
            nr, nc = PR, PC - 1
        elif dir_str == 'right':
            nr, nc = PR, PC + 1
        elif dir_str == 'up':
            nr, nc = PR - 1, PC
        elif dir_str == 'down':
            nr, nc = PR + 1, PC
        else:
            return False
        if not in_bounds(nr, nc):
            return False
        target = view[nr][nc]
        # only step if grass, sand or path and free
        return target in ('grass', 'sand', 'path')

    def safe_move_towards(tr, tc):
        dr = tr - PR
        dc = tc - PC
        dir_pref = dir_to(dr, dc)
        if dir_pref and move_valid_dir(dir_pref):
            return facing_action_for(dir_pref)
        # try orthogonal alternative that reduces Manhattan distance
        options = []
        if dr < 0:
            options.append('up')
        elif dr > 0:
            options.append('down')
        if dc < 0:
            options.append('left')
        elif dc > 0:
            options.append('right')
        for d in options:
            if move_valid_dir(d):
                return facing_action_for(d)
        # fallback wander but choose safe direction
        for d in ['up', 'left', 'right', 'down']:
            if move_valid_dir(d):
                return facing_action_for(d)
        # if no stepable, at least turn toward preferred
        if dir_pref:
            return facing_action_for(dir_pref)
        return NOOP

    def face_and_do_to(target_r, target_c):
        dr = target_r - PR
        dc = target_c - PC
        if abs(dc) > abs(dr):
            dir_str = 'left' if dc < 0 else 'right'
        else:
            dir_str = 'up' if dr < 0 else 'down'
        if facing == dir_str:
            return DO
        else:
            return facing_action_for(dir_str)

    def find_free_adjacent():
        for d, (nr, nc) in [('up', (PR - 1, PC)), ('left', (PR, PC - 1)), ('right', (PR, PC + 1)), ('down', (PR + 1, PC))]:
            if in_bounds(nr, nc) and view[nr][nc] in ('grass', 'sand', 'path'):
                return d
        return None

    def table_in_3x3():
        for r in range(PR - 1, PR + 2):
            for c in range(PC - 1, PC + 2):
                if in_bounds(r, c) and view[r][c] == 'table':
                    return (r, c)
        return None

    def furnace_in_3x3():
        for r in range(PR - 1, PR + 2):
            for c in range(PC - 1, PC + 2):
                if in_bounds(r, c) and view[r][c] == 'furnace':
                    return (r, c)
        return None

    def enemies_adjacent():
        for r, c in [(PR-1, PC), (PR+1, PC), (PR, PC-1), (PR, PC+1)]:
            if in_bounds(r, c) and view[r][c] in ('zombie', 'skeleton'):
                return True
        return False

    def nearest_enemy():
        return nearest(['zombie', 'skeleton'])

    def enemies_in_3x3():
        lst = []
        for r in range(PR-1, PR+2):
            for c in range(PC-1, PC+2):
                if in_bounds(r, c) and view[r][c] in ('zombie', 'skeleton'):
                    lst.append((r, c))
        return lst

    def flee_from(enemies):
        # compute sum vector away from enemies (orthogonal)
        vr = 0
        vc = 0
        for er, ec in enemies:
            vr += (PR - er)
            vc += (PC - ec)
        # prefer direction with larger magnitude
        if abs(vr) >= abs(vc):
            if vr > 0 and move_valid_dir('down'):
                return MOVE_DOWN
            elif vr < 0 and move_valid_dir('up'):
                return MOVE_UP
        if vc > 0 and move_valid_dir('right'):
            return MOVE_RIGHT
        elif vc < 0 and move_valid_dir('left'):
            return MOVE_LEFT
        # fallback try any safe move
        for d in ['up', 'left', 'right', 'down']:
            if move_valid_dir(d):
                return facing_action_for(d)
        return NOOP

    def wander():
        # deterministic-ish random walk with preference for safe moves
        order = ['up', 'left', 'right', 'down']
        # shuffle in a reproducible manner per step
        order = sorted(order, key=lambda x: (rnd.random(), x))
        for d in order:
            if move_valid_dir(d):
                return facing_action_for(d)
        # if no valid stepable move, just turn randomly
        return facing_action_for(rnd.choice(['up', 'left', 'right', 'down']))

    # Attempt tracking helpers to avoid repeated futile craft attempts
    def blocked(action):
        a = memory['attempts'].get(action)
        if not a:
            return False
        return a.get('blocked_until', 0) > memory['step']

    def start_attempt(action):
        if action not in memory['attempts']:
            memory['attempts'][action] = {
                'count': 0,
                'first_step': memory['step'],
                'snapshot': inv.copy(),
                'blocked_until': 0
            }

