    # Preemptive survival: if enemies adjacent, prioritize fight/flee
    if enemies_adjacent():
        # If we have a sword, attack the adjacent enemy. Prefer attacking over sleeping.
        if inv.get('iron_sword', 0) + inv.get('stone_sword', 0) + inv.get('wood_sword', 0) > 0:
            # find adjacent enemy cell and face/do it
            for r, c in [(PR-1, PC), (PR, PC-1), (PR, PC+1), (PR+1, PC)]:
                if in_bounds(r, c) and view[r][c] in ('zombie', 'skeleton'):
