            # If cannot flee, still try to attack with DO if adjacent (better than nothing)
            for r, c in [(PR-1, PC), (PR, PC-1), (PR, PC+1), (PR+1, PC)]:
                if in_bounds(r, c) and view[r][c] in ('zombie', 'skeleton'):
                    return int(face_and_do_to(r, c))
            # fallback to noop to avoid suicide moves
            return NOOP

    # Avoid sleeping if enemies in 3x3
    if sleeping:
