MOVE_RIGHT = 2
MOVE_UP = 3
MOVE_DOWN = 4
DO = 5
SLEEP = 6
PLACE_STONE = 7
PLACE_TABLE = 8
PLACE_FURNACE = 9
PLACE_PLANT = 10
MAKE_WOOD_PICK = 11
MAKE_STONE_PICK = 12
MAKE_IRON_PICK = 13
MAKE_WOOD_SWORD = 14
MAKE_STONE_SWORD = 15
MAKE_IRON_SWORD = 16

# player location in view
PR = 3
PC = 4

# mapping craft actions -> inventory key that should increase
CRAFT_KEY = {
    MAKE_WOOD_PICK: 'wood_pickaxe',
    MAKE_STONE_PICK: 'stone_pickaxe',
    MAKE_IRON_PICK: 'iron_pickaxe',
    MAKE_WOOD_SWORD: 'wood_sword',
    MAKE_STONE_SWORD: 'stone_sword',
    MAKE_IRON_SWORD: 'iron_sword',
}

def controller(obs, memory) -> int:
    view = obs['view']
    inv = obs['inventory']
    facing = obs['facing']
    daylight = obs.get('daylight', 1.0)
    sleeping = obs.get('sleeping', False)
    last_action = obs.get('last_action', None)  # integer or None

    # initialize memory
    if 'step' not in memory:
        memory['step'] = 0
    memory['step'] += 1

    if 'phase' not in memory:
        memory['phase'] = 1
    if 'attempts' not in memory:
        # attempts[action] = {'count': int, 'first_step': int, 'snapshot': {...}, 'blocked_until': step}
        memory['attempts'] = {}
    if 'blocked_actions' not in memory:
        memory['blocked_actions'] = {}
    if 'last_exec' not in memory:
        memory['last_exec'] = None
    if 'wander_seed' not in memory:
        memory['wander_seed'] = random.randint(0, 1000000)
    if 'noop_streak' not in memory:
        memory['noop_streak'] = 0
    if 'last_request' not in memory:
        memory['last_request'] = None

    rnd = random.Random(memory['wander_seed'] + memory['step'])

    # Helpers
    def in_bounds(r, c):
        return 0 <= r < 7 and 0 <= c < 9

    def cell(r, c):
        if not in_bounds(r, c):
            return 'edge'
        return view[r][c]

    def find_all(names):
        if isinstance(names, str):
            names = [names]
        coords = []
        for r in range(7):
            for c in range(9):
                if view[r][c] in names:
                    coords.append((r, c))
        return coords

    def nearest(target_names):
        if isinstance(target_names, str):
            target_names = [target_names]
        best = None
        bestd = 999
        for r in range(7):
            for c in range(9):
                if view[r][c] in target_names:
                    d = abs(r - PR) + abs(c - PC)
                    if d < bestd:
                        bestd = d
                        best = (r, c)
        return best

    def dir_to(dr, dc):
        if abs(dr) >= abs(dc):
            if dr < 0:
                return 'up'
            elif dr > 0:
                return 'down'
        if dc < 0:
            return 'left'
        elif dc > 0:
            return 'right'
        return None

    def facing_action_for(dir_str):
        return {'left': MOVE_LEFT, 'right': MOVE_RIGHT, 'up': MOVE_UP, 'down': MOVE_DOWN}[dir_str]

    def move_valid_dir(dir_str):
        if dir_str == 'left':
            nr, nc = PR, PC - 1
        elif dir_str == 'right':
            nr, nc = PR, PC + 1
        elif dir_str == 'up':
            nr, nc = PR - 1, PC
        elif dir_str == 'down':
            nr, nc = PR + 1, PC
        else:
            return False
        if not in_bounds(nr, nc):
            return False
        target = view[nr][nc]
        # only step if grass, sand or path and free
        return target in ('grass', 'sand', 'path')

    def safe_move_towards(tr, tc):
        dr = tr - PR
        dc = tc - PC
        dir_pref = dir_to(dr, dc)
        if dir_pref and move_valid_dir(dir_pref):
            return facing_action_for(dir_pref)
        options = []
        if dr < 0:
            options.append('up')
        elif dr > 0:
            options.append('down')
        if dc < 0:
            options.append('left')
        elif dc > 0:
            options.append('right')
        for d in options:
            if move_valid_dir(d):
                return facing_action_for(d)
        # fallback safe move
        for d in ['up', 'left', 'right', 'down']:
            if move_valid_dir(d):
                return facing_action_for(d)
        # if no safe step, at least face the preferred direction
        if dir_pref:
            return facing_action_for(dir_pref)
        return NOOP

    def face_and_do_to(target_r, target_c):
        dr = target_r - PR
        dc = target_c - PC
        if abs(dc) > abs(dr):
            dir_str = 'left' if dc < 0 else 'right'
        else:
            dir_str = 'up' if dr < 0 else 'down'
        if facing == dir_str:
            return DO
        else:
            return facing_action_for(dir_str)

    def find_free_adjacent():
        for d, (nr, nc) in [('up', (PR - 1, PC)), ('left', (PR, PC - 1)), ('right', (PR, PC + 1)), ('down', (PR + 1, PC))]:
            if in_bounds(nr, nc) and view[nr][nc] in ('grass', 'sand', 'path'):
                return d
        return None

    def table_in_3x3():
        for r in range(PR - 1, PR + 2):
            for c in range(PC - 1, PC + 2):
                if in_bounds(r, c) and view[r][c] == 'table':
                    return (r, c)
        return None

    def furnace_in_3x3():
        for r in range(PR - 1, PR + 2):
            for c in range(PC - 1, PC + 2):
                if in_bounds(r, c) and view[r][c] == 'furnace':
                    return (r, c)
        return None

    def enemies_adjacent():
        for r, c in [(PR-1, PC), (PR+1, PC), (PR, PC-1), (PR, PC+1)]:
            if in_bounds(r, c) and view[r][c] in ('zombie', 'skeleton'):
                return True
        return False

    def enemies_in_view():
        return find_all(['zombie', 'skeleton'])

    def enemies_in_3x3():
        lst = []
        for r in range(PR-1, PR+2):
            for c in range(PC-1, PC+2):
                if in_bounds(r, c) and view[r][c] in ('zombie', 'skeleton'):
                    lst.append((r, c))
        return lst

    def flee_from(enemies):
        vr = 0
        vc = 0
        for er, ec in enemies:
            vr += (PR - er)
            vc += (PC - ec)
        if abs(vr) >= abs(vc):
            if vr > 0 and move_valid_dir('down'):
                return MOVE_DOWN
            elif vr < 0 and move_valid_dir('up'):
                return MOVE_UP
        if vc > 0 and move_valid_dir('right'):
            return MOVE_RIGHT
        elif vc < 0 and move_valid_dir('left'):
            return MOVE_LEFT
        for d in ['up', 'left', 'right', 'down']:
            if move_valid_dir(d):
                return facing_action_for(d)
        return NOOP

    def wander():
        order = ['up', 'left', 'right', 'down']
        order = sorted(order, key=lambda x: (rnd.random(), x))
        for d in order:
            if move_valid_dir(d):
                return facing_action_for(d)
        return facing_action_for(rnd.choice(['up', 'left', 'right', 'down']))

    # Attempt tracking and blocking helpers
    def blocked(action):
        # blocked by time window or explicit block
        if memory['blocked_actions'].get(action, 0) > memory['step']:
            return True
        a = memory['attempts'].get(action)
        if not a:
            return False
        return a.get('blocked_until', 0) > memory['step']

    def start_attempt(action):
        if action not in memory['attempts']:
            memory['attempts'][action] = {
                'count': 0,
                'first_step': memory['step'],
                'snapshot': inv.copy(),
                'blocked_until': 0
            }

    def note_executed(action):
        # Called when last_action equals some action (i.e., executed by env)
        a = memory['attempts'].get(action)
        if not a:
            # create a minimal record to track success
            memory['attempts'][action] = {'count': 1, 'first_step': memory['step'], 'snapshot': inv.copy(), 'blocked_until': 0}
            a = memory['attempts'][action]
        else:
            a['count'] = a.get('count', 0) + 1
        a['last_step'] = memory['step']
        # check for craft success by inventory change relative to snapshot
        if action in CRAFT_KEY:
            key = CRAFT_KEY[action]
            if inv.get(key, 0) > a['snapshot'].get(key, 0):
                memory['attempts'].pop(action, None)
                memory['blocked_actions'].pop(action, None)
                return True
            # if executed repeatedly without producing item, block for some time
            if a['count'] >= 2:
                a['blocked_until'] = memory['step'] + 200
                memory['blocked_actions'][action] = memory['step'] + 200
                return False
        # generic guard
        if a['count'] >= 6:
            a['blocked_until'] = memory['step'] + 400
            memory['blocked_actions'][action] = memory['step'] + 400
        return False

    # If other policy executed an action (last_action), update attempt records
    if last_action is not None:
        executed = last_action
        if executed in memory['attempts']:
            note_executed(executed)
        memory['last_exec'] = executed

    # Track NOOP streak to avoid getting stuck in NOOP mode
    if last_action == NOOP:
        memory['noop_streak'] += 1
    else:
        memory['noop_streak'] = 0

    # If we requested an action previously and it was not executed, penalize repeated requests:
    prev_req = memory.get('last_request')
    if prev_req is not None and last_action != prev_req:
        # previous request didn't execute; temporarily block repeating it
        # but only if we requested a craft or placement; otherwise it's OK to repeat moves
        if prev_req in CRAFT_KEY or prev_req in (PLACE_TABLE, PLACE_FURNACE, PLACE_PLANT):
            memory['blocked_actions'][prev_req] = max(memory['blocked_actions'].get(prev_req, 0), memory['step'] + 30)
    # Clear last_request snapshot each step (we'll set it again at end)
    memory['last_request'] = None

    # Phase progression based on inventory/structures
    phase = memory['phase']
    if phase == 1:
        memory['phase'] = 2
        phase = 2
    if phase <= 3 and inv.get('wood', 0) >= 2:
        memory['phase'] = 3
        phase = 3
    if phase <= 4 and inv.get('wood_pickaxe', 0) >= 1 and inv.get('wood_sword', 0) >= 1:
        memory['phase'] = 5
        phase = 5
    if phase == 5 and inv.get('stone', 0) >= 1 and inv.get('coal', 0) >= 1:
        memory['phase'] = 7
        phase = 7
    if phase == 7 and inv.get('stone_pickaxe', 0) >= 1 and inv.get('stone_sword', 0) >= 1:
        memory['phase'] = 8
        phase = 8
    if phase == 8 and inv.get('iron', 0) >= 1:
        memory['phase'] = 10
        phase = 10
    if phase == 10 and furnace_in_3x3():
        memory['phase'] = 11
        phase = 11
    if phase == 11 and inv.get('iron_pickaxe', 0) >= 1 and inv.get('iron_sword', 0) >= 1:
        memory['phase'] = 12
        phase = 12
    if phase == 12 and inv.get('diamond', 0) >= 1:
        memory['phase'] = 13
        phase = 13
    if phase == 13 and inv.get('sapling', 0) >= 1:
        memory['phase'] = 15
        phase = 15
    if phase == 15 and inv.get('sapling', 0) <= 0:
        memory['phase'] = 16
        phase = 16
    if phase == 16 and inv.get('drink', 0) > 0:
        memory['phase'] = 17
        phase = 17
    if phase == 17 and inv.get('food', 0) > 0:
        memory['phase'] = 18
        phase = 18
    if phase == 18 and inv.get('energy', 0) > 80 and not sleeping:
        memory['phase'] = 19
        phase = 19

    # Preemptive survival behaviour
    # If zombies anywhere and we don't have decent sword, avoid exploring and try to get to table/furnace or move away
    zombies = find_all('zombie')
    if zombies and (inv.get('iron_sword', 0) + inv.get('stone_sword', 0) + inv.get('wood_sword', 0) == 0):
        # try to move toward table/furnace (safe spot) if present in view, else flee from nearest zombie
        f = nearest(['furnace'])
        t = nearest(['table'])
        if t:
            action = safe_move_towards(t[0], t[1])
            memory['last_request'] = action
            return int(action)
        if f:
            action = safe_move_towards(f[0], f[1])
            memory['last_request'] = action
            return int(action)
        # flee from nearest zombie
        nearest_z = min(zombies, key=lambda z: abs(z[0]-PR)+abs(z[1]-PC))
        es = [nearest_z]
        action = flee_from(es)
        memory['last_request'] = action
        return int(action)

    # If enemies adjacent, prioritize attack or flee as before
    if enemies_adjacent():
        # try to attack if have sword
        if inv.get('iron_sword', 0) + inv.get('stone_sword', 0) + inv.get('wood_sword', 0) > 0:
            for r, c in [(PR-1, PC), (PR, PC-1), (PR, PC+1), (PR+1, PC)]:
                if in_bounds(r, c) and view[r][c] in ('zombie', 'skeleton'):
                    act = face_and_do_to(r, c)
                    memory['last_request'] = act
                    return int(act)
        else:
            es = enemies_in_3x3()
            mv = flee_from(es)
            memory['last_request'] = mv
            return int(mv)

    # If currently sleeping, continue unless enemies in view
    if sleeping:
        if enemies_in_view():
            return NOOP
        return SLEEP

    # Survival diversion: if food/drink/energy dangerously low, prioritize them
    if inv.get('food', 0) <= 0 or inv.get('drink', 0) <= 0 or inv.get('energy', 0) < 30:
        # prioritize drink if none
        if inv.get('drink', 0) <= 0 and find_all('water'):
            act = go_to = None
            tgt = nearest(['water'])
            if tgt:
                if abs(tgt[0]-PR)+abs(tgt[1]-PC) == 1:
                    act = face_and_do_to(tgt[0], tgt[1])
                else:
                    act = safe_move_towards(tgt[0], tgt[1])
                memory['last_request'] = act
                return int(act)
        # prioritize food: cows or ripe plants
        if inv.get('food', 0) <= 0 and (find_all('cow') or find_all('plant_ripe')):
            tgt = nearest(['cow', 'plant_ripe'])
            if tgt:
                if abs(tgt[0]-PR)+abs(tgt[1]-PC) == 1:
                    act = face_and_do_to(tgt[0], tgt[1])
                else:
                    act = safe_move_towards(tgt[0], tgt[1])
                memory['last_request'] = act
                return int(act)
        # if energy low, try to sleep only if no enemies anywhere and energy very low
        if inv.get('energy', 0) < 20 and not enemies_in_view():
            memory['last_request'] = SLEEP
            return int(SLEEP)
        # otherwise continue with phase tasks but more cautious

    # Helper to go to resource(s)
    def go_to_resource(names):
        tgt = nearest(names)
        if not tgt:
            return wander()
        tr, tc = tgt
        if abs(tr - PR) + abs(tc - PC) == 1:
            return face_and_do_to(tr, tc)
        return safe_move_towards(tr, tc)

    # Craft attempt helper with improved blocking and fallback
    def try_craft(action_id):
        # do not craft if blocked
        if blocked(action_id):
            return NOOP
        # do not craft if already have the item
        key = CRAFT_KEY.get(action_id)
        if key and inv.get(key, 0) > 0:
            return NOOP
        # resource checks
        if action_id in (MAKE_WOOD_PICK, MAKE_WOOD_SWORD):
            if inv.get('wood', 0) < 1:
                return NOOP
        if action_id in (MAKE_STONE_PICK, MAKE_STONE_SWORD):
            if inv.get('wood', 0) < 1 or inv.get('stone', 0) < 1:
                return NOOP
        if action_id in (MAKE_IRON_PICK, MAKE_IRON_SWORD):
            if inv.get('wood', 0) < 1 or inv.get('coal', 0) < 1 or inv.get('iron', 0) < 1:
                return NOOP
        # table/furnace checks
        if not table_in_3x3():
            tbl = nearest(['table'])
            if tbl:
                return safe_move_towards(tbl[0], tbl[1])
            else:
                return NOOP
        if action_id in (MAKE_IRON_PICK, MAKE_IRON_SWORD) and not furnace_in_3x3():
            f = nearest(['furnace'])
            if f:
                return safe_move_towards(f[0], f[1])
            else:
                return NOOP
        # if we requested this craft previously but it wasn't executed, avoid spamming: block for short time
        prev = memory.get('last_request')
        if prev == action_id and last_action != action_id:
            memory['blocked_actions'][action_id] = memory['step'] + 40
            return NOOP
        # start attempt tracking and issue craft
        start_attempt(action_id)
        return action_id

    # Phase-driven action selection (refined)
    action = NOOP

    if phase == 2:
        if inv.get('wood', 0) >= 2:
            memory['phase'] = 3
            action = NOOP
        else:
            if find_all('tree'):
                action = go_to_resource(['tree'])
            else:
                action = wander()

    elif phase == 3:
        if table_in_3x3():
            memory['phase'] = 4
            action = NOOP
        elif inv.get('wood', 0) >= 2:
            d = find_free_adjacent()
            if d is None:
                action = wander()
            else:
                action = PLACE_TABLE if facing == d else facing_action_for(d)
        else:
            action = go_to_resource(['tree'])

    elif phase == 4:
        if not table_in_3x3():
            tbl = nearest(['table'])
            if tbl:
                action = safe_move_towards(tbl[0], tbl[1])
            else:
                action = wander()
        else:
            if inv.get('wood_pickaxe', 0) == 0:
                action = try_craft(MAKE_WOOD_PICK)
            elif inv.get('wood_sword', 0) == 0:
                action = try_craft(MAKE_WOOD_SWORD)
            else:
                memory['phase'] = 5
                action = NOOP

    elif phase == 5:
        if inv.get('stone', 0) >= 1 and inv.get('coal', 0) >= 1:
            memory['phase'] = 7
            action = NOOP
        else:
            action = go_to_resource(['stone', 'coal'])

    elif phase == 7:
        if not table_in_3x3():
            tbl = nearest(['table'])
            if tbl:
                action = safe_move_towards(tbl[0], tbl[1])
            else:
                action = wander()
        else:
            if inv.get('stone_pickaxe', 0) == 0 and inv.get('wood', 0) >= 1 and inv.get('stone', 0) >= 1:
                action = try_craft(MAKE_STONE_PICK)
            elif inv.get('stone_sword', 0) == 0 and inv.get('wood', 0) >= 1 and inv.get('stone', 0) >= 1:
                action = try_craft(MAKE_STONE_SWORD)
            else:
                memory['phase'] = 8
                action = NOOP

    elif phase == 8:
        if inv.get('iron', 0) >= 1:
            memory['phase'] = 10
            action = NOOP
        else:
            action = go_to_resource(['iron', 'coal', 'stone'])

    elif phase == 10:
        if furnace_in_3x3():
            memory['phase'] = 11
            action = NOOP
        elif inv.get('stone', 0) >= 4 and table_in_3x3():
            d = find_free_adjacent()
            if d is None:
                action = wander()
            else:
                action = PLACE_FURNACE if facing == d else facing_action_for(d)
        else:
            tbl = nearest(['table'])
            if tbl:
                action = safe_move_towards(tbl[0], tbl[1])
            else:
                action = go_to_resource(['stone'])

    elif phase == 11:
        if not table_in_3x3() or not furnace_in_3x3():
            f = nearest(['furnace'])
            if f:
                action = safe_move_towards(f[0], f[1])
            else:
                t = nearest(['table'])
                if t:
                    action = safe_move_towards(t[0], t[1])
                else:
                    action = wander()
        else:
            if inv.get('iron_pickaxe', 0) == 0:
                action = try_craft(MAKE_IRON_PICK)
            elif inv.get('iron_sword', 0) == 0:
                action = try_craft(MAKE_IRON_SWORD)
            else:
                memory['phase'] = 12
                action = NOOP

    elif phase == 12:
        if inv.get('diamond', 0) >= 1:
            memory['phase'] = 13
            action = NOOP
        else:
            if find_all('diamond'):
                action = go_to_resource(['diamond'])
            elif find_all('plant_ripe'):
                action = go_to_resource(['plant_ripe'])
            else:
                g = nearest(['grass'])
                if g:
                    if abs(g[0]-PR)+abs(g[1]-PC) == 1:
                        action = face_and_do_to(g[0], g[1])
                    else:
                        action = safe_move_towards(g[0], g[1])
                else:
                    action = wander()

    elif phase == 13:
        if inv.get('diamond', 0) >= 1:
            memory['phase'] = 14
            action = NOOP
        else:
            if inv.get('iron_pickaxe', 0) >= 1 and find_all('diamond'):
                action = go_to_resource(['diamond'])
            else:
                action = wander()

    elif phase == 14:
        if inv.get('sapling', 0) >= 1:
            memory['phase'] = 15
            action = NOOP
        else:
            g = nearest(['grass'])
            if g:
                if abs(g[0]-PR)+abs(g[1]-PC) == 1:
                    action = face_and_do_to(g[0], g[1])
                else:
                    action = safe_move_towards(g[0], g[1])
            else:
                action = wander()

    elif phase == 15:
        if inv.get('sapling', 0) <= 0:
            memory['phase'] = 16
            action = NOOP
        else:
            for d, (nr, nc) in [('up', (PR-1, PC)), ('left', (PR, PC-1)), ('right', (PR, PC+1)), ('down', (PR+1, PC))]:
                if in_bounds(nr, nc) and view[nr][nc] == 'grass':
                    action = PLACE_PLANT if facing == d else facing_action_for(d)
                    break
            else:
                g = nearest(['grass'])
                if g:
                    action = safe_move_towards(g[0], g[1])
                else:
                    action = wander()

    elif phase == 16:
        if inv.get('drink', 0) > 0:
            memory['phase'] = 17
            action = NOOP
        else:
            if find_all('water'):
                action = go_to_resource(['water'])
            else:
                action = wander()

    elif phase == 17:
        if inv.get('food', 0) > 0:
            memory['phase'] = 18
            action = NOOP
        else:
            if find_all('cow') or find_all('plant_ripe'):
                action = go_to_resource(['cow', 'plant_ripe'])
            else:
                action = wander()

    elif phase == 18:
        # Sleep only if energy very low and safe (reduce over-sleeping)
        if inv.get('energy', 0) < 20 and not enemies_in_view():
            action = SLEEP
        else:
            memory['phase'] = 19
            action = NOOP

    elif phase == 19:
        e = nearest(['zombie', 'skeleton'])
        if e:
            er, ec = e
            if abs(er - PR) + abs(ec - PC) == 1:
                action = face_and_do_to(er, ec)
            else:
                # approach if we have a sword, else avoid
                if inv.get('iron_sword', 0) + inv.get('stone_sword', 0) + inv.get('wood_sword', 0) > 0:
                    action = safe_move_towards(er, ec)
                else:
                    # avoid enemies, wander towards table or away
                    t = nearest(['table']) or nearest(['furnace'])
                    if t:
                        action = safe_move_towards(t[0], t[1])
                    else:
                        action = wander()
        else:
            if find_all('cow') or find_all('plant_ripe'):
                action = go_to_resource(['cow', 'plant_ripe'])
            else:
                action = wander()

    else:
        action = wander()

    # Safety and anti-stuck measures before returning

    # If craft requested but blocked, prefer wandering rather than NOOP
    if action in CRAFT_KEY and blocked(action):
        action = wander()

    # If action is a craft or place but table/furnace missing, prefer moving to them
    if action in CRAFT_KEY:
        if not table_in_3x3():
            tbl = nearest(['table'])
            if tbl:
                action = safe_move_towards(tbl[0], tbl[1])
            else:
                action = wander()
        elif action in (MAKE_IRON_PICK, MAKE_IRON_SWORD) and not furnace_in_3x3():
            f = nearest(['furnace'])
            if f:
                action = safe_move_towards(f[0], f[1])
            else:
                action = wander()

    # Avoid placing items onto invalid cell
    if action in (PLACE_TABLE, PLACE_FURNACE, PLACE_PLANT, PLACE_STONE):
        if facing == 'left':
            fr, fc = PR, PC - 1
        elif facing == 'right':
            fr, fc = PR, PC + 1
        elif facing == 'up':
            fr, fc = PR - 1, PC
        else:
            fr, fc = PR + 1, PC
        if not in_bounds(fr, fc) or view[fr][fc] not in ('grass', 'sand', 'path'):
            d = find_free_adjacent()
            if d:
                action = facing_action_for(d)
            else:
                action = wander()

    # Avoid sleeping when enemies anywhere
    if action == SLEEP and enemies_in_view():
        action = wander()

    # If we have been seeing long run of NOOPs (other policy interfering), prefer moving
    if memory['noop_streak'] >= 6 and action == NOOP:
        action = wander()

    # If our last request wasn't executed and we are about to request the same craft, block short-term
    if action in CRAFT_KEY:
        prev_req = memory.get('last_request')
        if prev_req == action and last_action != action:
            memory['blocked_actions'][action] = memory['step'] + 80
            action = wander()

    # Set last_request and return
    memory['last_request'] = action
    return int(action)
